// One row per review, stamped with the run date and keyed by review ID, so
// the sheet reads as a review history: an ID in this week's rows that is
// missing from last week's is a new review.
const weekOf = $now.toFormat('yyyy-MM-dd');
const threshold = Number($('Set the hotels to watch').first().json.alertAtOrBelow ?? 2);

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

// tripDate is only ever month accurate (it always lands on a month end), so
// it ships as YYYY-MM rather than pretending to be the exact night of the stay.
// Trip type arrives upper case with NONE standing in for "not stated".
const tripType = (t) => {
  const v = String(t || '').trim().toUpperCase();
  if (!v || v === 'NONE') return '';
  return v.charAt(0) + v.slice(1).toLowerCase();
};

return $input.all().map((item) => {
  const r = item.json;
  const rating = typeof r.rating === 'number' ? r.rating : '';
  return {
    json: {
      'Week of': weekOf,
      'Hotel place ID': r.placeId || '',
      'Total reviews': typeof r.totalReviews === 'number' ? r.totalReviews : '',
      'Review ID': r.reviewId || '',
      Position: r.position ?? '',
      Rating: rating,
      'Needs a reply': rating !== '' && rating <= threshold ? 'YES' : '',
      'Review date': r.reviewDate || '',
      'Stay month': String(r.tripDate || '').slice(0, 7),
      Title: clip(r.title, 140),
      Review: clip(r.snippet, 300),
      'Trip type': tripType(r.tripType),
      Language: r.language || '',
      Author: clip(r.authorName, 80),
      'Review URL': r.url || '',
    },
  };
});

